  __shared__ T sX_raw[SX_ELEMS];
  Tensor sX = make_tensor(make_smem_ptr(sX_raw),
                          make_shape(Int<CI_CHUNK>{}, Int<IN_TILE>{}, Int<IN_TILE>{}, Int<IN_TILE>{}),
                          make_stride(Int<IN_TILE*IN_TILE*IN_TILE>{},
