  const int oxg = ox0 + ox;
  const bool out_valid = (ozg < Dout) && (oyg < Hout) && (oxg < Wout);

  int co_a[NACC];
  bool co_valid[NACC];
  float acc[NACC];

  #pragma unroll
  for (int a = 0; a < NACC; ++a) {
    // +4 comes from 256 threads / 64 spatial points; striding covers all 24 output channels.
    int co_local = cq + 4 * a;
    int co = co_tile * CO_TILE + co_local;
    co_a[a] = co;
    co_valid[a] = (co_local < CO_TILE) && (co < OC);
    float b0 = 0.0f;
    if (B != nullptr && co_valid[a]) {
      b0 = (float)B[co];
    }
    acc[a] = b0;
  }

  // Input halo origin for this output brick.
  const int iz0 = oz0 + padding - (K3 - 1);
  const int iy0 = oy0 + padding - (K3 - 1);
  const int ix0 = ox0 + padding - (K3 - 1);

  for (int ci0 = 0; ci0 < C; ci0 += CI_CHUNK) {
    // Cooperative load of the input halo for CI_CHUNK input channels.
    for (int e = tid; e < SX_ELEMS; e += THREADS) {
      int cil = e / (IN_TILE * IN_TILE * IN_TILE);
      int rem = e - cil * (IN_TILE * IN_TILE * IN_TILE);
      int liz = rem / (IN_TILE * IN_TILE);
      int rem2 = rem - liz * (IN_TILE * IN_TILE);
      int liy = rem2 / IN_TILE;
      int lix = rem2 - liy * IN_TILE;

      int ci = ci0 + cil;
      int gz = iz0 + liz;
      int gy = iy0 + liy;
      int gx = ix0 + lix;

      T v = T(0);
      if (ci < C &&
          (unsigned)gz < (unsigned)Din &&
          (unsigned)gy < (unsigned)Hin &&
          (unsigned)gx < (unsigned)Win) {
        v = mX(n, ci, gz, gy, gx);
      }
      sX(cil, liz, liy, lix) = v;
    }
    __syncthreads();

    if (out_valid) {
      const int ci_lim = min(CI_CHUNK, C - ci0);
      #pragma unroll
      for (int cil = 0; cil < CI_CHUNK; ++cil) {
        if (cil >= ci_lim) break;
        const int ci = ci0 + cil;

        #pragma unroll
        for (int kz = 0; kz < K3; ++kz) {
          const int liz = oz + (K3 - 1) - kz;
          #pragma unroll
          for (int ky = 0; ky < K3; ++ky) {
            const int liy = oy + (K3 - 1) - ky;
            #pragma unroll
            for (int kx = 0; kx < K3; ++kx) {
              const int lix = ox + (K3 - 1) - kx;
              const float xv = (float)sX(cil, liz, liy, lix);

              #pragma unroll
              for (int a = 0; a < NACC; ++a) {
                if (co_valid[a]) {
                  const float wv = (float)mW(ci, co_a[a], kz, ky, kx);
                  acc[a] = fmaf(xv, wv, acc[a]);
                }
              }
            }
          }
        }
      }
    }
    __syncthreads();
  }

  #pragma unroll
  for (int a = 0; a < NACC; ++a) {
    if (out_valid && co_valid[a]) {
      mY(n, co_a[a], ozg, oyg, oxg) = (T)acc[a];
    }
  }
}

torch::Tensor conv_transpose3d_cute_forward(torch::Tensor x,
                                            torch::Tensor weight,
                                            c10::optional<torch::Tensor> bias,
                                            int64_t stride,
                                            int64_t padding,
                                            int64_t output_padding,
                                            int64_t dilation,
                                            int64_t groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  if (bias.has_value()) TORCH_CHECK(bias.value().is_cuda(), "bias must be CUDA when provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  if (bias.has_value()) TORCH_CHECK(bias.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 5, "x must be [N, C, D, H, W]");
  TORCH_CHECK(weight.dim() == 5, "weight must be [Cin, Cout, kD, kH, kW]");

  TORCH_CHECK(groups == 1, "custom CUTE kernel currently supports groups=1");
  TORCH_CHECK(stride == 1, "custom CUTE kernel currently supports stride=1");
  TORCH_CHECK(dilation == 1, "custom CUTE kernel currently supports dilation=1");
  TORCH_CHECK(output_padding == 0, "custom CUTE kernel currently supports output_padding=0");
  TORCH_CHECK(weight.size(2) == 3 && weight.size(3) == 3 && weight.size(4) == 3,
              "custom CUTE kernel is specialized for kernel_size=3");

  const int64_t N = x.size(0);
  const int64_t C = x.size(1);
  const int64_t Din = x.size(2);
  const int64_t Hin = x.size(3);
  const int64_t Win = x.size(4);

  const int64_t OC = weight.size(1);
  TORCH_CHECK(weight.size(0) == C, "weight.size(0) must equal in_channels for groups=1");
  if (bias.has_value()) {
    TORCH_CHECK(bias.value().dim() == 1 && bias.value().size(0) == OC, "bias must be [out_channels]");
  }

  const int64_t Dout = (Din - 1) * stride - 2 * padding + dilation * (3 - 1) + output_padding + 1;
  const int64_t Hout = (Hin - 1) * stride - 2 * padding + dilation * (3 - 1) + output_padding + 1;
  const int64_t Wout = (Win - 1) * stride - 2 * padding + dilation * (3 - 1) + output_padding + 1;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "invalid transposed-convolution output size");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value()) {
    b_c = bias.value().contiguous();
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, OC, Dout, Hout, Wout}, x.options());

  constexpr int TILE = 4;
  const int64_t tiles_d = (Dout + TILE - 1) / TILE;
  const int64_t tiles_h = (Hout + TILE - 1) / TILE;
  const int64_t tiles_w = (Wout + TILE - 1) / TILE;
  const int64_t spatial_tiles = tiles_d * tiles_h * tiles_w;
  const int64_t co_tiles = (OC + 24 - 1) / 24;

  dim3 block(256);
  dim3 grid((unsigned)spatial_tiles, (unsigned)co_tiles, (unsigned)N);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  convt3d_s1_kernel<float, 3><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)C, (int)Din, (int)Hin, (int)Win,
      (int)OC, (int)Dout, (int)Hout, (int)Wout,
      (int)padding);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "convt3d_s1_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
